/**
 * O braço do polvo — porte de `componentes/viz/polvo.js`.
 *
 * Um braço sem ossos tem infinitas maneiras de se mexer, e controlar isso seria
 * impossível. O polvo resolve criando uma DOBRA temporária — um pseudo-cotovelo
 * — que parte o braço em dois trechos quase rígidos. De repente o problema vira
 * o mesmo do nosso braço, com duas articulações, e o cérebro dá conta.
 *
 * Por isso o controle é o ponto da dobra, e não o alcance: é a dobra que resolve.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

type Ponto = readonly [number, number];

const polvo: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /**
   * Uma faixa afilada ao longo de uma linha: para cada ponto, anda meia-espessura
   * para cada lado da normal. Devolve as duas bordas, que as ventosas usam.
   */
  function tentaculo(
    ctx: CanvasRenderingContext2D,
    linha: readonly Ponto[],
    meiaEspessura: (u: number) => number,
    preenchimento: string,
    contorno: string,
  ): { esquerda: Ponto[]; direita: Ponto[] } {
    const esquerda: Ponto[] = [];
    const direita: Ponto[] = [];

    for (let i = 0; i < linha.length; i++) {
      const a = linha[Math.max(0, i - 1)] ?? [0, 0];
      const b = linha[Math.min(linha.length - 1, i + 1)] ?? [0, 0];
      const atual = linha[i] ?? [0, 0];

      let nx = -(b[1] - a[1]);
      let ny = b[0] - a[0];
      const m = Math.hypot(nx, ny) || 1;
      nx /= m;
      ny /= m;

      const hw = meiaEspessura(i / (linha.length - 1));
      esquerda.push([atual[0] + nx * hw, atual[1] + ny * hw]);
      direita.push([atual[0] - nx * hw, atual[1] - ny * hw]);
    }

    ctx.beginPath();
    const primeiro = esquerda[0] ?? [0, 0];
    ctx.moveTo(primeiro[0], primeiro[1]);
    for (let i = 1; i < esquerda.length; i++) {
      const p = esquerda[i] ?? [0, 0];
      ctx.lineTo(p[0], p[1]);
    }
    for (let i = direita.length - 1; i >= 0; i--) {
      const p = direita[i] ?? [0, 0];
      ctx.lineTo(p[0], p[1]);
    }
    ctx.closePath();

    ctx.fillStyle = preenchimento;
    ctx.fill();
    ctx.strokeStyle = contorno;
    ctx.lineWidth = 1.2;
    ctx.stroke();

    return { esquerda, direita };
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const dobra = Math.max(0, numeroDe(valores, 'd', 0));
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Um cotovelo que não existe');

    const baseX = L * 0.22;
    const baseY = A * 0.56;
    const presaX = L * 0.8;
    const presaY = A * 0.4;
    const corBraco = ok ? '#3fbf88' : '#a55a99';
    const corEscura = ok ? '#1c8f4f' : '#6e3a64';

    // ── O corpo do polvo ──────────────────────────────────────────────────
    // Tudo daqui para baixo sai de `E`. Os tamanhos eram literais em pixels, e
    // o bicho ficava do mesmo tamanho em qualquer tela — miúdo no telefone.
    const E = limitar(Math.min(L * 0.055, A * 0.085), 12, 26);
    const mantoX = L * 0.11;

    // As outras seis pernas, atrás do manto: um polvo tem oito, e desenhar
    // três dizia "lula". Ondulam devagar, cada uma na sua fase.
    ctx.strokeStyle = '#7d3872';
    ctx.lineCap = 'round';
    for (const [i, dy] of [-0.5, 0.2, 0.9, 1.5, 2.1, 2.6].entries()) {
      const fase = t * 1.2 + i;
      ctx.lineWidth = E * (0.42 - i * 0.03);
      ctx.beginPath();
      // Cada braço nasce num ponto diferente da borda da cabeça; saindo todos
      // do mesmo lugar, os seis viravam um tufo só.
      ctx.moveTo(mantoX + E * (0.2 - i * 0.16), baseY + E * dy * 0.55);
      ctx.bezierCurveTo(
        mantoX + E * (1.4 + Math.sin(fase) * 0.3),
        baseY + E * (dy * 0.55 + 0.5),
        mantoX + E * (0.6 + Math.cos(fase) * 0.5),
        baseY + E * (dy * 0.55 + 1.5),
        mantoX + E * (1.3 + Math.sin(fase + 1) * 0.6),
        baseY + E * (dy * 0.55 + 2.1),
      );
      ctx.stroke();
    }

    // O manto, com o gradiente que lhe dá volume.
    const volume = ctx.createLinearGradient(mantoX - E, baseY - E * 3, mantoX + E, baseY + E);
    volume.addColorStop(0, '#a85c9a');
    volume.addColorStop(1, '#7d3872');
    ctx.fillStyle = volume;
    ctx.beginPath();
    ctx.ellipse(mantoX, baseY - E * 1.35, E * 1.05, E * 1.5, 0, 0, Math.PI * 2);
    ctx.fill();

    // As papilas: as saliências que o polvo levanta na pele para se camuflar.
    ctx.fillStyle = 'rgb(60 20 52 / 22%)';
    for (let i = 0; i < 9; i++) {
      const ang = (i / 9) * Math.PI * 2;
      ctx.beginPath();
      ctx.ellipse(
        mantoX + Math.cos(ang) * E * 0.55,
        baseY - E * 1.35 + Math.sin(ang) * E * 0.8,
        E * 0.12,
        E * 0.09,
        0,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }

    // A cabeça, mais clara que o manto.
    ctx.fillStyle = '#9b4d8e';
    ctx.beginPath();
    ctx.ellipse(mantoX + E * 0.18, baseY + E * 0.1, E * 1.3, E * 1.1, 0, 0, Math.PI * 2);
    ctx.fill();

    // Os olhos — a pupila do polvo é uma FENDA HORIZONTAL, e é ela que dá o
    // olhar estranho do bicho. Uma bolinha redonda o fazia parecer um boneco.
    for (const dx of [-0.42, 0.55]) {
      const ox = mantoX + E * dx;
      const oy = baseY - E * 0.22;

      ctx.fillStyle = '#e8c86a';
      ctx.beginPath();
      ctx.ellipse(ox, oy, E * 0.34, E * 0.26, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#6e3a64';
      ctx.lineWidth = 1;
      ctx.stroke();

      ctx.fillStyle = '#3a1530';
      ctx.beginPath();
      ctx.roundRect(ox - E * 0.22, oy - E * 0.055, E * 0.44, E * 0.11, E * 0.05);
      ctx.fill();

      ctx.fillStyle = 'rgb(255 255 255 / 55%)';
      ctx.beginPath();
      ctx.arc(ox - E * 0.14, oy - E * 0.13, E * 0.07, 0, Math.PI * 2);
      ctx.fill();
    }

    // O sifão, por onde ele expulsa a água para se impulsionar.
    ctx.fillStyle = '#86407a';
    ctx.beginPath();
    ctx.ellipse(mantoX - E * 0.85, baseY + E * 0.35, E * 0.28, E * 0.16, -0.5, 0, Math.PI * 2);
    ctx.fill();

    // O braço ativo: dois trechos retos ligados pela dobra.
    const cotX = baseX + (presaX - baseX) * (dobra / 100) * 0.95;
    const cotY = baseY - (dobra / 100) * A * 0.16 - 6;
    const alcance = ok ? 1 : 0.8;
    const pontaX = cotX + (presaX - cotX) * alcance;
    const pontaY = cotY + (presaY - cotY) * alcance;

    // O vinco no cotovelo fica de propósito: é ele o assunto do módulo.
    const linha: Ponto[] = [];
    const N = 14;
    for (let i = 0; i <= N; i++) {
      const s = i / N;
      linha.push([baseX + (cotX - baseX) * s, baseY + (cotY - baseY) * s]);
    }
    for (let i = 1; i <= N; i++) {
      const s = i / N;
      linha.push([cotX + (pontaX - cotX) * s, cotY + (pontaY - cotY) * s]);
    }
    const ultimo = linha[linha.length - 1] ?? [0, 0];
    linha.push([ultimo[0] + (ok ? 6 : 3), ultimo[1] + (ok ? -2 : 4)]);

    const { esquerda, direita } = tentaculo(
      ctx,
      linha,
      (u) => E * 0.62 * (1 - u) * (1 - u) + 1.6,
      corBraco,
      corEscura,
    );

    // As duas fileiras de ventosas.
    ctx.fillStyle = cor.contraste;
    for (let i = 1; i < linha.length - 1; i++) {
      const u = i / (linha.length - 1);
      const r = Math.max(1.2, E * 0.2 * (1 - u));
      const centro = linha[i] ?? [0, 0];

      for (const borda of [esquerda, direita]) {
        const b = borda[i] ?? [0, 0];
        ctx.beginPath();
        ctx.arc(
          centro[0] + (b[0] - centro[0]) * 0.5,
          centro[1] + (b[1] - centro[1]) * 0.5,
          r,
          0,
          Math.PI * 2,
        );
        ctx.fill();
      }
    }

    // A marca da dobra.
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([3, 2]);
    ctx.beginPath();
    ctx.arc(cotX, cotY, 14, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    texto(ctx, 'dobra', cotX, cotY - 22, limitar(A * 0.036, 9, 12), {
      cor: cor.fraco,
      peso: 700,
    });

    // A presa.
    ctx.fillStyle = ok ? cor.verde : '#c07a3a';
    ctx.beginPath();
    ctx.ellipse(presaX, presaY, 13, 9, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = ok ? cor.verde : '#c07a3a';
    ctx.lineWidth = 2;
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(presaX + lado * 11, presaY - 3);
      ctx.lineTo(presaX + lado * 19, presaY - 11);
      ctx.lineTo(presaX + lado * 22, presaY - 6);
      ctx.stroke();

      for (let k = -2; k <= 2; k++) {
        ctx.beginPath();
        ctx.moveTo(presaX + lado * 6, presaY + 2);
        ctx.lineTo(presaX + lado * 16, presaY + 6 + k * 2);
        ctx.stroke();
      }
    }

    if (ok) {
      ctx.strokeStyle = cor.verde;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.arc(presaX, presaY, 18 + Math.sin(t * 5) * 3, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      'A dobra partiu o braço em dois trechos rígidos ✔',
      'Ajuste o ponto da dobra até a ponta alcançar a presa.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default polvo;
